async def act(page):
    # Use the site-search helper to find articles matching 'Americast'.
    # According to the knowledge-base, this helper begins by navigating to '/'.
    results = await create_curated_collection_by_search(page, 'Americast', max_results=10, resolve_links=True)

    # Print the helper's raw return value exactly as received (per instructions about APIs/helpers).
    print(results)

    # Find a candidate whose title contains 'Americast' (case-insensitive)
    candidate = None
    try:
        for r in results:
            title = r.get('title', '')
            if title and 'amercast' in title.lower():
                candidate = r
                break
    except Exception:
        candidate = None

    if not candidate:
        # Try to find a direct link on the current page as a fallback (accessible link named 'Americast')
        try:
            link_locator = page.get_by_role('link', name='Americast')
            if await link_locator.count() > 0:
                # Get href attribute from the first matching link
                href = await link_locator.nth(0).get_attribute('href')
                if href:
                    candidate = {'title': 'Americast', 'url': href}
        except Exception:
            candidate = None

    if not candidate:
        # No article found; print a clear negative result
        print({'found_article': False, 'image_related_to_amercast': False})
        return

    # Navigate to the candidate article URL.
    url = candidate.get('url')
    if not url:
        print({'found_article': True, 'url': None, 'image_related_to_amercast': False})
        return

    # If url is relative, navigation will handle it (page.goto accepts relative URLs when same origin).
    await page.goto(url)
    # Wait briefly for potential client-side rendering
    try:
        await page.wait_for_load_state('networkidle')
    except Exception:
        pass

    # Inspect images on the page via accessibility role 'img'
    img_locator = page.get_by_role('img')
    img_count = 0
    try:
        img_count = await img_locator.count()
    except Exception:
        img_count = 0

    found = False
    found_info = None
    for i in range(img_count):
        try:
            img = img_locator.nth(i)
            alt = await img.get_attribute('alt') or ''
            src = await img.get_attribute('src') or ''
            # Check if alt or src contains the substring 'amercast' (case-insensitive)
            if 'amercast' in (alt or '').lower() or 'amercast' in (src or '').lower():
                found = True
                found_info = {'alt': alt, 'src': src}
                break
        except Exception:
            continue

    # Print a structured result
    if found:
        print({'found_article': True, 'url': url, 'image_related_to_amercast': True, 'matching_image': found_info})
    else:
        print({'found_article': True, 'url': url, 'image_related_to_amercast': False})

